 let manifest=read("/home/ubuntu/src/zopro-perf-work/adopted-c7a239/production-manifest.json");for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());}let canonical=Path::new("/home/ubuntu/src/zopro-perf-work/adopted-c7a239/local/smoke-output/proof-sha256.json");assert_eq!(hash(canonical),"c2407f7fd7d43e32a685db92664fc94facac7c2608ba7843419be07629700cf3");assert_eq!(read(canonical).as_array().unwrap().len(),62191);
 save(r.join("timing.json"),json!({"protocol_to_first_result_seconds":first-start,"protocol_to_finish_seconds":now-start,"active_capture_seconds":active,"preparation_allowance_seconds":1200,"capture_allowance_seconds":120,"preparation_allowance_pass":first-start<=1200.,"capture_allowance_pass":active<=120.,"clock_scope":"Protocol modification to assessment/result; earlier paper/history research is outside; no AWS-authentication wait subtracted"}));save(r.join("receipts.json"),json!({"passed":true,"receipts":rows,"commands":32,"failed_compile_commands":1,"stream_hashes":64,"successful_capture_commands":28}));
