 let qraw=fs::read_to_string(r.join("build-run-v2/exact-product-qualification/stdout.log")).unwrap();save(r.join("qualification.json"),serde_json::from_str(qraw.trim().strip_prefix("QUALIFY ").unwrap()).unwrap());
 let asm=fs::read_to_string(r.join("probe.asm")).unwrap();let mut chosen=String::new();let mut selected=false;for l in asm.lines(){if l.ends_with(">:"){selected=["<probe::integer>:","<probe::floating>:","<probe::floating_raw>:"].iter().any(|n|l.ends_with(n));}if selected{chosen.push_str(l);chosen.push('\n');}}fs::write(r.join("selected.asm"),chosen).unwrap();
 fs::create_dir_all(d.join("artifacts")).unwrap();for n in["protocol.md","assessment.json","review-plan.json","review-smoke.json","review-main.json","qualification.json","timing.json","receipts.json","auth-and-readiness.json"]{fs::copy(r.join(n),d.join("artifacts").join(n)).unwrap();}
